// Package checks runs the per-task verification commands of a scenario.
//
// Checks are generated by an LLM, so they are never passed to a shell: each
// command is split into arguments and must be a read-only kubectl invocation.
package checks

import (
	"context"
	"fmt"
	"os/exec"
	"regexp"
	"strings"
	"time"

	"github.com/galalen/ckad-trainer/models"
)

const (
	MatchEquals   = "equals"
	MatchContains = "contains"
	MatchRegex    = "regex"
	MatchExit0    = "exit0"
)

// readOnlyVerbs are the kubectl subcommands a check may use. "rollout" and
// "auth" are further restricted by readOnlySubcommands.
var readOnlyVerbs = map[string]bool{
	"get":           true,
	"describe":      true,
	"logs":          true,
	"auth":          true,
	"rollout":       true,
	"top":           true,
	"exec":          true,
	"explain":       true,
	"api-resources": true,
	"version":       true,
}

var readOnlySubcommands = map[string]map[string]bool{
	"rollout": {"status": true, "history": true},
	"auth":    {"can-i": true, "whoami": true},
}

// Runner executes kubectl with the given arguments and returns combined output.
type Runner func(ctx context.Context, args []string) (string, error)

// KubectlRunner runs the real kubectl binary.
func KubectlRunner(ctx context.Context, args []string) (string, error) {
	out, err := exec.CommandContext(ctx, "kubectl", args...).CombinedOutput()
	return string(out), err
}

// Result is the outcome of a single check.
type Result struct {
	Check  models.Check
	Passed bool
	Output string
	Err    error
}

// TaskResult aggregates the check results of one task.
type TaskResult struct {
	Task    models.Task
	Results []Result
}

func (t TaskResult) Passed() bool {
	if len(t.Results) == 0 {
		return false
	}
	for _, r := range t.Results {
		if !r.Passed {
			return false
		}
	}
	return true
}

// ParseCommand splits a check command into kubectl arguments and verifies
// that it is a read-only kubectl invocation.
func ParseCommand(cmd string) ([]string, error) {
	args, err := SplitArgs(cmd)
	if err != nil {
		return nil, err
	}
	if len(args) == 0 || args[0] != "kubectl" {
		return nil, fmt.Errorf("check must start with kubectl: %q", cmd)
	}
	args = args[1:]

	verb := firstPositional(args)
	if !readOnlyVerbs[verb] {
		return nil, fmt.Errorf("kubectl %q is not allowed in checks", verb)
	}
	if allowed, ok := readOnlySubcommands[verb]; ok {
		sub := firstPositional(args[indexOf(args, verb)+1:])
		if !allowed[sub] {
			return nil, fmt.Errorf("kubectl %s %q is not allowed in checks", verb, sub)
		}
	}
	return args, nil
}

// Validate reports whether every check of the scenario is well-formed.
func Validate(s models.Scenario) error {
	if len(s.Tasks) == 0 {
		return fmt.Errorf("scenario has no tasks")
	}
	for i, t := range s.Tasks {
		if len(t.Checks) == 0 {
			return fmt.Errorf("task %d has no checks", i+1)
		}
		for _, c := range t.Checks {
			if _, err := ParseCommand(c.Cmd); err != nil {
				return fmt.Errorf("task %d: %w", i+1, err)
			}
			if c.Match == MatchRegex {
				if _, err := regexp.Compile(c.Expect); err != nil {
					return fmt.Errorf("task %d: invalid regex %q: %w", i+1, c.Expect, err)
				}
			}
		}
	}
	return nil
}

// RunTask runs every check of a task.
func RunTask(ctx context.Context, run Runner, task models.Task, timeout time.Duration) TaskResult {
	tr := TaskResult{Task: task}
	for _, c := range task.Checks {
		tr.Results = append(tr.Results, RunCheck(ctx, run, c, timeout))
	}
	return tr
}

// RunCheck runs a single check and compares its output with the expectation.
func RunCheck(ctx context.Context, run Runner, c models.Check, timeout time.Duration) Result {
	res := Result{Check: c}

	args, err := ParseCommand(c.Cmd)
	if err != nil {
		res.Err = err
		return res
	}

	cctx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()

	out, runErr := run(cctx, args)
	res.Output = strings.TrimSpace(out)

	match := c.Match
	if match == "" {
		match = MatchEquals
		if c.Expect == "" {
			match = MatchExit0
		}
	}

	if runErr != nil {
		res.Err = runErr
		return res
	}

	switch match {
	case MatchExit0:
		res.Passed = true
	case MatchEquals:
		res.Passed = normalize(res.Output) == normalize(c.Expect)
	case MatchContains:
		res.Passed = strings.Contains(res.Output, c.Expect)
	case MatchRegex:
		re, err := regexp.Compile(c.Expect)
		if err != nil {
			res.Err = fmt.Errorf("invalid regex %q: %w", c.Expect, err)
			return res
		}
		res.Passed = re.MatchString(res.Output)
	default:
		res.Err = fmt.Errorf("unknown match type %q", match)
	}
	return res
}

// normalize trims whitespace and surrounding quotes that jsonpath output
// commonly carries when the LLM quotes the expected value.
func normalize(s string) string {
	return strings.Trim(strings.TrimSpace(s), `'"`)
}

func firstPositional(args []string) string {
	i := indexOfPositional(args)
	if i < 0 {
		return ""
	}
	return args[i]
}

// indexOfPositional skips global flags such as "-n ns" or "--context=x".
func indexOfPositional(args []string) int {
	for i := 0; i < len(args); i++ {
		a := args[i]
		if !strings.HasPrefix(a, "-") {
			return i
		}
		if !strings.Contains(a, "=") && flagTakesValue(a) {
			i++
		}
	}
	return -1
}

func flagTakesValue(flag string) bool {
	switch flag {
	case "-n", "--namespace", "--context", "--kubeconfig", "--cluster", "--user", "-s", "--server":
		return true
	}
	return false
}

func indexOf(args []string, s string) int {
	for i, a := range args {
		if a == s {
			return i
		}
	}
	return -1
}

// SplitArgs splits a command line into arguments, honouring single quotes,
// double quotes and backslash escapes. Shell operators are rejected so a
// check cannot chain or redirect commands.
func SplitArgs(s string) ([]string, error) {
	var (
		args    []string
		cur     strings.Builder
		inArg   bool
		quote   rune
		escaped bool
	)

	for _, r := range s {
		switch {
		case escaped:
			cur.WriteRune(r)
			escaped = false
		case quote == '\'':
			if r == '\'' {
				quote = 0
			} else {
				cur.WriteRune(r)
			}
		case quote == '"':
			switch r {
			case '"':
				quote = 0
			case '\\':
				escaped = true
			default:
				cur.WriteRune(r)
			}
		case r == '\'' || r == '"':
			quote = r
			inArg = true
		case r == '\\':
			escaped = true
			inArg = true
		case r == ' ' || r == '\t' || r == '\n':
			if inArg {
				args = append(args, cur.String())
				cur.Reset()
				inArg = false
			}
		case strings.ContainsRune("|;&><`$", r):
			return nil, fmt.Errorf("shell operator %q is not allowed in checks", r)
		default:
			cur.WriteRune(r)
			inArg = true
		}
	}

	if quote != 0 {
		return nil, fmt.Errorf("unterminated quote in %q", s)
	}
	if escaped {
		return nil, fmt.Errorf("trailing backslash in %q", s)
	}
	if inArg {
		args = append(args, cur.String())
	}
	return args, nil
}
